test('tasks validate, preserve order, isolate projects, and persist completion', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-tasks-'));
  const dbPath = join(directory, 'workboard.sqlite');
  let server;
  let url;
  async function start() {
    server = createApp(dbPath);
    server.listen(0, '127.0.0.1');
    await once(server, 'listening');
    url = `http://127.0.0.1:${server.address().port}`;
  }
  async function stop() {
    await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
    server = undefined;
  }
  const request = (path, method = 'GET', body) => fetch(url + path, {
    method,
    headers: { 'Content-Type': 'application/json' },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
  });
  const data = async (path, method, body) => (await request(path, method, body)).json();
  try {
    await start();
    const first = await data('/api/projects', 'POST', { name: 'First' });
    const second = await data('/api/projects', 'POST', { name: 'Second' });
    const path = `/api/projects/${first.id}/tasks`;
    const otherPath = `/api/projects/${second.id}/tasks`;
    for (const title of ['', ' \n\t ', null, 123]) {
      const response = await request(path, 'POST', { title });
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await data(path), []);
    const response = await request(path, 'POST', { title: '  First task  ' });
    assert.equal(response.status, 201);
    const task = await response.json();
    assert.equal(task.title, 'First task');
    assert.equal(task.completed, false);
    const next = await data(path, 'POST', { title: '<b>Second task</b>' });
    assert.deepEqual(await data(path), [task, next]);
    assert.deepEqual(await data(otherPath), []);
    assert.equal((await request(`${otherPath}/${task.id}`, 'PATCH', { completed: true })).status, 404);
    for (const completed of [1, 'true', null]) {
      assert.equal((await request(`${path}/${task.id}`, 'PATCH', { completed })).status, 400);
    }
    const completed = await data(`${path}/${task.id}`, 'PATCH', { completed: true });
    assert.deepEqual(completed, { ...task, completed: true });
    const otherTask = await data(otherPath, 'POST', { title: 'Other project task' });
    assert.deepEqual(await data(path), [completed, next]);
    assert.equal((await request('/api/projects/999999/tasks', 'POST', { title: 'Missing' })).status, 404);
    const malformed = await fetch(url + path, { method: 'POST', body: '{' });
    assert.equal(malformed.status, 400);
    await stop();
    await start();
    assert.deepEqual(await data(path), [completed, next]);
    assert.deepEqual(await data(otherPath), [otherTask]);
    const page = await request(`/projects/${first.id}`);
    assert.equal(page.status, 200);
    const html = await page.text();
    assert.match(html, /<label for="task-title">Task title<\/label>/);
    assert.match(html, /Create task/);
    assert.match(html, /<label for="task-filter">Task filter<\/label>/);
    for (const option of ['All', 'Open', 'Completed']) {
      assert.ok(html.includes(`>${option}</option>`));
    }
